insert into public.collections (name, slug, description, position) values ('Core Edition', 'core-edition', 'The pieces we return to.', 0)
insert into public.collections (name, slug, description, position) values ('New Arrivals', 'new-arrivals', 'The latest from the studio.', 1)
insert into public.collections (name, slug, description, position) values ('Best Sellers', 'best-sellers', 'Quietly essential, worn on repeat.', 2)
insert into public.products (name, slug, description, details, care, category_id, collection_id, price_cents, compare_at_price_cents, currency, badge, is_featured, is_new, status) values ('Heavyweight Oversized Tee', 'heavyweight-oversized-tee', 'The Heavyweight Oversized Tee is built from compact combed cotton with a dry, structured hand. A wide body, dropped shoulder and ribbed crew neck keep the silhouette clean without feeling oversized for the sake of it.', array['260gsm compact combed cotton', 'Dropped shoulder with a wide body', 'Ribbed crew neck', 'Pre-shrunk and garment-washed']::text[], 'Machine wash cold with like colours. Hang dry. Warm iron if needed.', (select id from public.categories where slug = 't-shirts'), (select id from public.collections where slug = 'core-edition'), 6500, null, 'USD', 'New', true, true, 'active')
insert into public.products (name, slug, description, details, care, category_id, collection_id, price_cents, compare_at_price_cents, currency, badge, is_featured, is_new, status) values ('Everyday Crew Tee', 'everyday-crew-tee', 'A midweight cotton crew neck with a neat body and a slightly shorter length. Designed to layer or wear alone, with a smooth hand that softens with every wash.', array['180gsm combed cotton jersey', 'Tubular body to prevent twisting', 'Ribbed crew neck', 'Slightly shorter body length']::text[], 'Machine wash cold. Tumble dry low. Warm iron if needed.', (select id from public.categories where slug = 't-shirts'), (select id from public.collections where slug = 'core-edition'), 4500, null, 'USD', null, true, false, 'active')
insert into public.products (name, slug, description, details, care, category_id, collection_id, price_cents, compare_at_price_cents, currency, badge, is_featured, is_new, status) values ('Heavyweight Pullover Hoodie', 'heavyweight-pullover-hoodie', 'Built for repeat wear, the Heavyweight Pullover Hoodie uses dense brushed-back French terry and a double-layer hood without drawstrings. The body is roomy but controlled, with a ribbed hem that holds its shape.', array['480gsm brushed-back French terry', 'Double-layer hood without drawstrings', 'Dropped shoulder', 'Ribbed cuffs and hem']::text[], 'Machine wash cold inside out. Hang dry. Do not tumble dry.', (select id from public.categories where slug = 'hoodies'), (select id from public.collections where slug = 'core-edition'), 11000, null, 'USD', 'New', true, true, 'active')
insert into public.products (name, slug, description, details, care, category_id, collection_id, price_cents, compare_at_price_cents, currency, badge, is_featured, is_new, status) values ('Relaxed Zip Hoodie', 'relaxed-zip-hoodie', 'The Relaxed Zip Hoodie is cut with a little extra room through the body and sleeve. A two-way zip and a soft double-layer hood make it an easy layer for transitional weather.', array['420gsm brushed cotton fleece', 'Two-way metal zip', 'Double-layer hood', 'Ribbed cuffs and hem']::text[], 'Machine wash cold. Hang dry. Warm iron if needed.', (select id from public.categories where slug = 'hoodies'), (select id from public.collections where slug = 'core-edition'), 11500, 13500, 'USD', 'Sale', true, false, 'active')
insert into public.products (name, slug, description, details, care, category_id, collection_id, price_cents, compare_at_price_cents, currency, badge, is_featured, is_new, status) values ('Relaxed Oxford Shirt', 'relaxed-oxford-shirt', 'The Relaxed Oxford Shirt is cut from washed cotton oxford with a natural drape. A relaxed collar, single chest pocket and curved hem make it equally at home open over a tee or buttoned to the top.', array['Washed cotton oxford', 'Relaxed point collar', 'Single chest pocket', 'Curved hem']::text[], 'Machine wash cold. Hang dry. Warm iron if needed.', (select id from public.categories where slug = 'shirts'), (select id from public.collections where slug = 'core-edition'), 9500, null, 'USD', null, true, false, 'active')
insert into public.products (name, slug, description, details, care, category_id, collection_id, price_cents, compare_at_price_cents, currency, badge, is_featured, is_new, status) values ('Linen Blend Overshirt', 'linen-blend-overshirt', 'Cut with the ease of a shirt and the utility of a light jacket, the Linen Blend Overshirt is made from a breathable linen-cotton weave. It softens with wear and works open over a tank or closed as a standalone layer.', array['Linen-cotton blend', 'Dual chest flap pockets', 'Natural horn buttons', 'Straight hem with side vents']::text[], 'Machine wash cold. Hang dry. Warm iron while slightly damp.', (select id from public.categories where slug = 'shirts'), (select id from public.collections where slug = 'new-arrivals'), 9500, null, 'USD', 'New', true, true, 'active')
insert into public.products (name, slug, description, details, care, category_id, collection_id, price_cents, compare_at_price_cents, currency, badge, is_featured, is_new, status) values ('Straight Leg Trousers', 'straight-leg-trousers', 'The Straight Leg Trouser is built from a dry cotton twill with enough weight to hold a crease. A mid rise and straight leg create a simple, architectural line that works with tees, knits and shirting.', array['Heavy cotton twill', 'Mid rise with a straight leg', 'Pressed front crease', 'Belt loops and side pockets']::text[], 'Machine wash cold. Hang dry. Warm iron if needed.', (select id from public.categories where slug = 'trousers'), (select id from public.collections where slug = 'core-edition'), 11000, null, 'USD', null, true, false, 'active')
insert into public.products (name, slug, description, details, care, category_id, collection_id, price_cents, compare_at_price_cents, currency, badge, is_featured, is_new, status) values ('Pleated Wide Trousers', 'pleated-wide-trousers', 'The Pleated Wide Trouser is cut from a soft wool blend with a single front pleat and a high rise. The leg falls wide and clean, with enough movement for everyday wear and enough structure for evening.', array['Wool-blend suiting', 'Single front pleat', 'High rise with a wide leg', 'Side seam pockets']::text[], 'Dry clean only.', (select id from public.categories where slug = 'trousers'), (select id from public.collections where slug = 'core-edition'), 12000, null, 'USD', 'New', true, true, 'active')
insert into public.products (name, slug, description, details, care, category_id, collection_id, price_cents, compare_at_price_cents, currency, badge, is_featured, is_new, status) values ('Coach Jacket', 'coach-jacket', 'A minimal take on the coach jacket, cut in a matte water-repellent shell. The snap front, pointed collar and clean hem keep the line sharp, while a light lining makes it easy to layer.', array['Water-repellent matte shell', 'Snap button front', 'Pointed collar', 'Lightweight lining']::text[], 'Wipe clean or machine wash cold on a gentle cycle. Hang dry.', (select id from public.categories where slug = 'jackets'), (select id from public.collections where slug = 'core-edition'), 13500, null, 'USD', null, true, false, 'active')
insert into public.products (name, slug, description, details, care, category_id, collection_id, price_cents, compare_at_price_cents, currency, badge, is_featured, is_new, status) values ('Lightweight Bomber', 'lightweight-bomber', 'The Lightweight Bomber is cut with a little extra room through the body and finished with a ribbed collar, cuffs and hem. A light insulation makes it a useful layer without the bulk.', array['Lightly insulated technical shell', 'Ribbed collar, cuffs and hem', 'Two-way front zip', 'Interior pocket']::text[], 'Machine wash cold on a gentle cycle. Hang dry. Do not iron.', (select id from public.categories where slug = 'jackets'), (select id from public.collections where slug = 'new-arrivals'), 14000, 16500, 'USD', 'Sale', true, true, 'active')
insert into public.products (name, slug, description, details, care, category_id, collection_id, price_cents, compare_at_price_cents, currency, badge, is_featured, is_new, status) values ('Canvas Tote', 'canvas-tote', 'The Canvas Tote is made from a heavy washed canvas with a wide base and reinforced handles. It holds a laptop, a notebook and the rest of the day without losing its shape.', array['Heavy washed cotton canvas', 'Wide base with interior pocket', 'Reinforced handles', 'Natural undyed finish']::text[], 'Spot clean with cold water. Air dry.', (select id from public.categories where slug = 'accessories'), (select id from public.collections where slug = 'core-edition'), 4000, null, 'USD', null, true, false, 'active')
insert into public.products (name, slug, description, details, care, category_id, collection_id, price_cents, compare_at_price_cents, currency, badge, is_featured, is_new, status) values ('Six-Panel Cotton Cap', 'six-panel-cotton-cap', 'A quiet everyday cap in washed cotton twill. The six-panel construction gives it a clean shape, while the curved brim and adjustable back keep it comfortable.', array['Washed cotton twill', 'Six-panel construction', 'Curved brim', 'Adjustable back strap']::text[], 'Spot clean with cold water. Air dry.', (select id from public.categories where slug = 'accessories'), (select id from public.collections where slug = 'new-arrivals'), 3500, null, 'USD', 'New', true, true, 'active')
